// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }
    function testFuzz_property(uint256 seed, address actor) public {
        // No setup can make an uninitialized, never-paused contract report an active pause.
        // vm.assume/bound: nothing to restrict; actor/seed are admissible for any value.
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool reported = c.paused();
        assertTrue(reported == false);
    }
}
